INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l46',3,10,46,'Do It Yourself','自己动手','So + 形容词 + be + 主语, that …(表语提前引起的倒装,强调)、过去分词短语作状语(Armed with …, Buried in the grass …)、短语动词 embark on / cater for / get round to / go so far as to、be supposed to / be faced with / be proved wrong(be + 过去分词固定搭配)、部分否定 not all …(并非人人都…)(原创承载 NCE3 第三册 L46 考点·无需净化:DIY 自己动手题材幽默故事——叙述者拆了自家割草机却装不回去;美式化 yard/store/repairman/labor)','如今我们自己动手做事的热情如此高涨,以至于越来越少依赖专业工人了。由于出版了数不清的教人自己动手的书和视频,没有人再能推说自己对某事一无所知。备好合适的工具和材料,新婚夫妇便兴高采烈地开始装点自己的新居。特别是男人,常利用空闲时间安装自家的灯具、布置自家的花园、搭建棚屋、打造家具。有些真正热心的爱好者甚至自己组装电脑。商店为了迎合这股自己动手的热潮,不仅为新手开设专门的咨询台,还向顾客出售可以拿回家自己组装的零件。这些东西为人们积压的创造力提供了一个绝妙的宣泄口,可惜的是,并非人人都是天生的巧匠。有些妻子往往认为自己的丈夫无比足智多谋、什么都能修。就连那些连一枚钉子都钉不直的男人,也被当成了天生的电工、木匠、水管工和机械师。每当保险丝烧断、家具松动摇晃、管道堵塞,或者洗碗机罢工,有些妻子总认为丈夫总能把事情摆平。自己动手这游戏最糟糕的一点是:有时连男人自己都活在一种错觉里,以为自己什么都行,哪怕已经一再被证明是错的。这多半是个面子问题。今年春天,妻子建议我请个修理工来看看我们家的割草机。那台机器去年夏天就坏了,尽管我答应过要修,却一直没抽出时间。我不愿听她的建议,说我自己会修。一个星期六的下午,我把机器拖到院子里,仔细看了一番。在我看来,它只需稍作调整:这儿拧拧螺丝,那儿紧一紧,再滴几滴油,就会像新的一样。可修理这活儿,不出所料,并没那么简单。割草机死活不肯割草,于是我决定把它拆开。院子里很快铺满了曾经组成一台割草机的金属块。但我对自己相当满意,因为我查出了毛病的根源:驱动轮子的链条上,有一节链环断了。买来新链条后,我却面对一项难以完成的任务——把这堆让人晕头转向的拼图重新拼回去。重新组装完毕后,机器仍旧罢工,我一点也不意外,原因很简单:我手里还剩下好几块形状古怪的金属,似乎哪儿都装不上。我绝望地放弃了。几周过去,草越长越高。妻子唠叨我该想想办法时,我告诉她:要么买台新割草机,要么就让草长着。不用说,我家现在四周成了一片丛林。深草丛中某处,埋着一台生了锈的割草机,我曾答应有朝一日把它修好。','{"q":"Listen and answer — Did the writer repair his lawn mower in the end? Why/Why not?","options":["No — he dismantled it but couldn''t put it back together, out of pride","Yes — he fixed it easily","Yes — with a repairman''s help","He never even tried"],"answer_index":0}'::jsonb,'{"title":"So + 形容词 + 倒装 / 过去分词作状语 / 短语动词 / be + 过去分词搭配 / 部分否定 not all","intro":"①为强调形容词,把 so + 形容词提到句首,主语与 be 动词要倒装:So great is our passion … that …。②过去分词短语作状语,表被动/完成:Armed with the right tools, …;Buried in the grass, the mower rusts。③短语动词:embark on(着手)、cater for(迎合)、get round to(抽空做)、go so far as to do(竟到…程度)。④be supposed to(理应/被认为)、be faced with(面对)、be proved wrong(被证明错)。⑤not all …:部分否定,“并非所有/人人都…”。","table":{"headers":["用法","意思","例子"],"rows":[["So + 形容词 + be + 主语, that","如此…以至于(倒装强调)","So great is our passion that …"],["过去分词短语作状语","被…/…后","Armed with tools, they …"],["embark on / get round to","着手 / 抽空做","never got round to it"],["not all …","并非人人/所有都…","not all of us are handymen"]]},"specialRules":[{"rule":"So + 形容词提前时,后面主谓要倒装:So great is our passion（× So great our passion is）;that 引导结果。","mark":"So great is …"},{"rule":"not all 是部分否定(并非全部),不是全否定;后面动词按名词单复数决定(not all of us are …)。","mark":"not all …"},{"rule":"美式:yard(英式 garden 指院子)、store(英式 shop)、repairman、labor(英式 labour)。本课已按美语写。","mark":"yard / store / labor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l46',1,NULL,'So great is our passion for doing things ourselves that we are becoming less and less dependent on skilled labor. No one can plead ignorance of a subject any longer, for there are countless do-it-yourself books and videos. Armed with the right tools and materials, newlyweds gaily embark on the task of decorating their own homes.','如今我们自己动手做事的热情如此高涨,以至于越来越少依赖专业工人了。由于出版了数不清的教人自己动手的书和视频,没有人再能推说自己对某事一无所知。备好合适的工具和材料,新婚夫妇便兴高采烈地开始装点自己的新居。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l46',2,NULL,'Men, in particular, spend hours of their leisure time installing their own light fixtures, laying out their own gardens, building sheds, and making furniture. Some really keen enthusiasts go so far as to build their own computers. Stores cater for the do-it-yourself craze not only by running special advice desks for novices, but by offering customers parts they can assemble at home. Such things provide an excellent outlet for pent-up creative energy, but unfortunately not all of us are born handymen.','特别是男人,常利用空闲时间安装自家的灯具、布置自家的花园、搭建棚屋、打造家具。有些真正热心的爱好者甚至自己组装电脑。商店为了迎合这股自己动手的热潮,不仅为新手开设专门的咨询台,还向顾客出售可以拿回家自己组装的零件。这些东西为人们积压的创造力提供了一个绝妙的宣泄口,可惜的是,并非人人都是天生的巧匠。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l46',3,NULL,'Some wives tend to believe that their husbands are endlessly resourceful and can fix anything. Even men who can hardly drive a nail in straight are supposed to be born electricians, carpenters, plumbers, and mechanics. When a fuse blows, furniture gets rickety, pipes get clogged, or the dishwasher fails to run, some women assume that their husbands will somehow put things right. The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything, even when they have repeatedly been proved wrong.','有些妻子往往认为自己的丈夫无比足智多谋、什么都能修。就连那些连一枚钉子都钉不直的男人,也被当成了天生的电工、木匠、水管工和机械师。每当保险丝烧断、家具松动摇晃、管道堵塞,或者洗碗机罢工,有些妻子总认为丈夫总能把事情摆平。自己动手这游戏最糟糕的一点是:有时连男人自己都活在一种错觉里,以为自己什么都行,哪怕已经一再被证明是错的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l46',4,NULL,'Last spring my wife suggested that I call in a repairman to look at our lawn mower. It had broken down the previous summer, and though I had promised to fix it, I had never gotten round to it. I would not hear of the suggestion and said that I would fix it myself. One Saturday afternoon I hauled the machine into the yard and took a close look at it. As far as I could see, it needed only a minor adjustment: a turn of a screw here, a little tightening there, a drop of oil, and it would be as good as new.','今年春天,妻子建议我请个修理工来看看我们家的割草机。那台机器去年夏天就坏了,尽管我答应过要修,却一直没抽出时间。我不愿听她的建议,说我自己会修。一个星期六的下午,我把机器拖到院子里,仔细看了一番。在我看来,它只需稍作调整:这儿拧拧螺丝,那儿紧一紧,再滴几滴油,就会像新的一样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l46',5,NULL,'The mower firmly refused to mow, so I decided to take it apart. The yard was soon littered with chunks of metal that had once made up a lawn mower. One of the links in the chain that drove the wheels had snapped. After buying a new chain, I was faced with the insurmountable task of putting the confusing jigsaw puzzle back together, but the machine still refused to work, for I was left with several oddly shaped bits of metal that did not seem to fit anywhere. I gave up in despair. When my wife nagged me, I told her that I would either buy a new mower or let the grass grow. Needless to say, our house is now surrounded by a jungle, and buried somewhere in the deep grass is a rusting lawn mower that I have promised to fix one day.','割草机死活不肯割草,于是我决定把它拆开。院子里很快铺满了曾经组成一台割草机的金属块。驱动轮子的链条上,有一节链环断了。买来新链条后,我却面对一项难以完成的任务——把这堆让人晕头转向的拼图重新拼回去,可机器仍旧罢工,因为我手里还剩下好几块形状古怪的金属,似乎哪儿都装不上。我绝望地放弃了。妻子唠叨我时,我告诉她:要么买台新割草机,要么就让草长着。不用说,我家现在四周成了一片丛林,深草丛中某处,埋着一台生了锈的割草机,我曾答应有朝一日把它修好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
