INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l46','embark on','',NULL,'/ɪmˈbɑːrk ɑːn/','Newlyweds embark on decorating their homes.','新婚夫妇着手装点新居。','She embarked on a new career.','她开始了一份新事业。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l46','go so far as to','',NULL,'/ɡoʊ soʊ fɑːr æz tə/','Some go so far as to build their own computers.','有些人竟自己组装电脑。','He went so far as to call me a liar.','他竟然说我是骗子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l46','get round to','',NULL,'/ɡet raʊnd tə/','I never got round to fixing it.','我一直没抽出时间去修它。','I''ll get round to it tomorrow.','我明天会抽空做。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l46','put things right','',NULL,'/pʊt θɪŋz raɪt/','Husbands are supposed to put things right.','丈夫理应把事情摆平。','He tried to put things right after the mistake.','出错后他设法弥补。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp1','choice','{"stem":"\"So great ___ our passion for doing things ourselves that we rely less on experts.\"(So + 形容词提前,主语与 be 倒装,填 be 动词)","options":["is","has","does","it is"],"answer_index":0,"stem_cn":"我们自己动手的热情如此高涨,以至于越来越少依赖专家。","explanation_cn":"为强调形容词,so + 形容词提到句首,主语与 be 动词倒装;主语 passion 单数,用 is。✓ So great is our passion … that … ✗ does / has(不与 great 搭配作系动词)/ it is(多了 it)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp1','choice','{"stem":"\"So keen ___ the enthusiasts that they build their own computers.\"(So + 形容词提前引起倒装,填 be 动词)","options":["do","they are","are","have"],"answer_index":2,"stem_cn":"爱好者们如此热心,竟自己组装电脑。","explanation_cn":"同理,So keen 提前引起倒装;主语 enthusiasts 复数,用 are。✓ So keen are the enthusiasts that … ✗ do / have / they are:倒装后紧跟 be 动词 are。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp1','choice','{"stem":"\"___ great is his pride that he refused all help.\"(程度词提前引起倒装,句首填哪个词)","options":["Such","Very","Too","So"],"answer_index":3,"stem_cn":"他自尊心太强,拒绝了一切帮助。","explanation_cn":"表示“如此…以至于”并引起倒装、后接 that 结果,句首用 So + 形容词。✓ So great is his pride that … ✗ Such(接名词)/ Very / Too:引起倒装 + that 的是 So。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp2','choice','{"stem":"\"___ with the right tools, newlyweds decorate their homes.\"(过去分词短语作状语:装备好…)","options":["Arming","Arm","Armed","To arm"],"answer_index":2,"stem_cn":"备好合适的工具,新婚夫妇装点新居。","explanation_cn":"过去分词短语作状语,表被动“被…装备好”;逻辑主语是后面的 newlyweds。✓ Armed with the right tools, newlyweds … ✗ Arming / Arm / To arm:表被动/完成用过去分词 Armed。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp2','choice','{"stem":"\"___ somewhere in the deep grass, the old mower slowly rusts.\"(过去分词短语作状语:被埋在…)","options":["Buried","Burying","To bury","Bury"],"answer_index":0,"stem_cn":"埋在深草丛某处,那台旧割草机慢慢生锈。","explanation_cn":"过去分词短语作状语,表被动“被埋在…”。✓ Buried somewhere in the grass, the mower rusts. ✗ Burying / Bury / To bury:被动用过去分词 Buried。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp2','choice','{"stem":"\"___ from the shed, the tools were covered in dust.\"(过去分词短语作状语:被取出)","options":["To take","Taken","Taking","Take"],"answer_index":1,"stem_cn":"从棚里取出时,工具落满灰尘。","explanation_cn":"过去分词短语作状语,表被动“被取出”。✓ Taken from the shed, the tools were dusty. ✗ Taking / Take / To take:被动用过去分词 Taken。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp3','choice','{"stem":"\"Newlyweds gaily embark ___ the task of decorating.\"(“着手、开始干”:embark ___)","options":["at","in","of","on"],"answer_index":3,"stem_cn":"新婚夫妇兴高采烈地开始装修。","explanation_cn":"embark on sth,“着手、开始做”;固定介词 on。✓ embark on the task of decorating. ✗ in / at / of:embark 搭配 on。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp3','choice','{"stem":"\"Some enthusiasts go so far ___ to build their own computers.\"(“竟到了…的程度”:go so far ___ to do)","options":["to","as","than","that"],"answer_index":1,"stem_cn":"有些爱好者竟自己组装电脑。","explanation_cn":"go so far as to do,“竟到了…的程度”;固定用 as … to do。✓ go so far as to build their own computers. ✗ than / that / to:固定搭配是 so far as to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp3','choice','{"stem":"\"I promised to fix it but never got ___ to it.\"(“抽出时间去做”:get ___ to sth 的固定副词)","options":["off","over","up","round"],"answer_index":3,"stem_cn":"我答应修,却一直没抽出时间。","explanation_cn":"get round to sth,“抽出时间去做”;固定副词 round。✓ never got round to it. ✗ over / off / up:固定搭配是 get round to。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp4','choice','{"stem":"\"Even clumsy men are ___ to be born handymen.\"(be ___ to be:被认为是、理应是)","options":["supposed","suppose","supposition","supposing"],"answer_index":0,"stem_cn":"连笨手笨脚的男人都被认为天生是能工巧匠。","explanation_cn":"be supposed to,“被认为、理应”。✓ are supposed to be born handymen. ✗ suppose / supposing / supposition:固定用过去分词 supposed。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp4','choice','{"stem":"\"After buying a chain, I was ___ with a huge task.\"(be ___ with:面对、面临)","options":["facing","faces","face","faced"],"answer_index":3,"stem_cn":"买了新链条后,我面对一项艰巨任务。","explanation_cn":"be faced with,“面对、面临”。✓ I was faced with a huge task. ✗ facing(此处用被动)/ face / faces:固定搭配用过去分词 faced。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp4','choice','{"stem":"\"Even when they have been ___ wrong, some men still boast.\"(be ___ wrong:被证明是错的,填过去分词)","options":["prove","proved","proof","proving"],"answer_index":1,"stem_cn":"即便一再被证明错了,有些男人仍吹嘘。","explanation_cn":"be proved wrong,“被证明是错的”;have been + 过去分词 proved。✓ they have been proved wrong. ✗ proving / prove / proof:被动完成用过去分词 proved。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp5','choice','{"stem":"\"Unfortunately, ___ all of us are born handymen.\"(部分否定:并非人人都…)","options":["not","none","no","never"],"answer_index":0,"stem_cn":"可惜并非人人都是天生的巧匠。","explanation_cn":"部分否定“并非人人都…”用 not all …。✓ not all of us are born handymen. ✗ no / none / never:部分否定与 all 连用的是 not。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp5','choice','{"stem":"\"Not ___ husband can really fix things.\"(部分否定:并非每个…)","options":["no","any","none","every"],"answer_index":3,"stem_cn":"并非每个丈夫都真能修东西。","explanation_cn":"部分否定“并非每个…”用 not every …。✓ Not every husband can fix things. ✗ no / none(全否定)/ any:与 not 构成部分否定的是 every。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp5','choice','{"stem":"\"Not all the parts ___ back into place.\"(部分否定,主句动词用复数)","options":["fit","fits","fitting","to fit"],"answer_index":0,"stem_cn":"并非所有零件都能装回原位。","explanation_cn":"not all the parts 主语是复数,动词用原形复数 fit。✓ Not all the parts fit back into place. ✗ fits(单数)/ fitting / to fit:复数主语用 fit。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp6','choice','{"stem":"\"To take a machine apart into pieces is to ___ it.\"(“拆卸”用哪个词)","options":["assemble","paint","polish","dismantle"],"answer_index":3,"stem_cn":"把机器拆成零件。","explanation_cn":"把机器拆成零件是 dismantle。✓ I decided to dismantle it. ✗ assemble 组装(相反);✗ polish 擦亮;✗ paint 粉刷——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp6','choice','{"stem":"\"A chair that is shaky and likely to fall apart is ___.\"(“摇晃的、要散架的”用哪个词)","options":["rickety","sturdy","brand-new","heavy"],"answer_index":0,"stem_cn":"摇摇晃晃、快散架的椅子。","explanation_cn":"摇摇晃晃、快散架是 rickety。✓ furniture gets rickety. ✗ sturdy 结实(相反);✗ brand-new 全新;✗ heavy 沉重——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',5,'am3_l46_gp6','choice','{"stem":"\"Someone clever at finding ways to solve problems is ___.\"(“足智多谋的”用哪个词)","options":["careless","timid","resourceful","lazy"],"answer_index":2,"stem_cn":"善于想办法解决问题的人。","explanation_cn":"善于想办法解决问题是 resourceful。✓ endlessly resourceful. ✗ lazy 懒惰;✗ careless 粗心;✗ timid 胆小——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"plead 的意思是:","options":["购买","找(借口),辩解","命令","赞美"],"answer_index":1,"explanation_cn":"plead = 找借口、辩解。✓ plead ignorance 推说无知。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"novice 的意思是:","options":["新手","工人","专家","顾客"],"answer_index":0,"explanation_cn":"novice = 新手。✓ advice desks for novices 为新手开设的咨询台。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"assemble 的意思是:","options":["拆开","装配,组装","丢弃","出售"],"answer_index":1,"explanation_cn":"assemble = 装配、组装。✓ parts they can assemble at home 可在家组装的零件。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"dismantle 的意思是:","options":["拆卸","组装","擦亮","搬运"],"answer_index":0,"explanation_cn":"dismantle = 拆卸。✓ I decided to dismantle it 我决定拆开它。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"resourceful 的意思是:","options":["粗心的","胆小的","懒惰的","足智多谋的"],"answer_index":3,"explanation_cn":"resourceful = 足智多谋的。✓ endlessly resourceful 无比足智多谋。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',6,NULL,'choice','{"stem":"insurmountable 的意思是:","options":["容易的","不能克服的,难以对付的","短暂的","常见的"],"answer_index":1,"explanation_cn":"insurmountable = 不能克服的、难以对付的。✓ the insurmountable task 难以完成的任务。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',7,NULL,'cloze','{"stem":"第 1 空","context":"So great ___1___ our passion for doing things ourselves that we depend less on skilled labor. Armed ___2___ the right tools, people happily decorate their own homes. But not ___3___ of us are born handymen. Last spring I decided to fix my own lawn mower. I took it apart but was then faced ___4___ the impossible task of putting it back together, and I gave up in despair.","blank_no":1,"options":["is","does","has","it is"],"answer_index":0,"explanation_cn":"So + 形容词提前引起倒装,主语 passion 单数,用 is。✓ So great is our passion that …"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',7,NULL,'cloze','{"stem":"第 2 空","context":"So great ___1___ our passion for doing things ourselves that we depend less on skilled labor. Armed ___2___ the right tools, people happily decorate their own homes. But not ___3___ of us are born handymen. Last spring I decided to fix my own lawn mower. I took it apart but was then faced ___4___ the impossible task of putting it back together, and I gave up in despair.","blank_no":2,"options":["with","by","of","for"],"answer_index":0,"explanation_cn":"过去分词 Armed 搭配 with,“备好…”。✓ Armed with the right tools."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',7,NULL,'cloze','{"stem":"第 3 空","context":"So great ___1___ our passion for doing things ourselves that we depend less on skilled labor. Armed ___2___ the right tools, people happily decorate their own homes. But not ___3___ of us are born handymen. Last spring I decided to fix my own lawn mower. I took it apart but was then faced ___4___ the impossible task of putting it back together, and I gave up in despair.","blank_no":3,"options":["all","none","any","some"],"answer_index":0,"explanation_cn":"部分否定 not all …,“并非人人都…”。✓ not all of us are born handymen."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',7,NULL,'cloze','{"stem":"第 4 空","context":"So great ___1___ our passion for doing things ourselves that we depend less on skilled labor. Armed ___2___ the right tools, people happily decorate their own homes. But not ___3___ of us are born handymen. Last spring I decided to fix my own lawn mower. I took it apart but was then faced ___4___ the impossible task of putting it back together, and I gave up in despair.","blank_no":4,"options":["with","to","of","for"],"answer_index":0,"explanation_cn":"be faced with,“面对、面临”。✓ faced with the impossible task."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',8,NULL,'choice','{"stem":"Did the writer repair his lawn mower in the end?","options":["Yes — a repairman fixed it","He bought a brand-new one instead","No — he took it apart but could not reassemble it","Yes — it worked perfectly"],"answer_index":2,"explanation_cn":"录音说他把割草机拆开后装不回去,剩下几块零件哪都装不上,最终放弃。✓ dismantled but could not reassemble."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',8,NULL,'choice','{"stem":"Why do some wives think their husbands can fix anything?","options":["Their husbands are trained mechanics","They believe their husbands are endlessly resourceful","Their husbands never fail","They read it in a book"],"answer_index":1,"explanation_cn":"录音说有些妻子认为丈夫无比足智多谋、什么都能修。✓ endlessly resourceful."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',8,NULL,'choice','{"stem":"What happened to the writer''s yard in the end?","options":["It was perfectly mowed","A gardener took care of it","It was paved over","The grass grew into a jungle around the house"],"answer_index":3,"explanation_cn":"录音说他一直没修好,草越长越高,房子四周成了一片丛林。✓ surrounded by a jungle."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',9,NULL,'choice','{"stem":"你想说\"我们自己动手的热情如此高涨\"(So + 形容词 + 倒装):","options":["So great is our passion for doing things ourselves are.","So great does our passion for doing things ourselves.","So great is our passion for doing things ourselves.","So great our passion is for doing things ourselves."],"answer_index":2,"explanation_cn":"So + 形容词提前后,要把 be 动词提到前面(is our passion),不保留正常语序。✓ So great is our passion … 场合:强调“如此…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',9,NULL,'choice','{"stem":"你想说\"有些人竟自己组装电脑\"(go so far as to do):","options":["Some go so far as build their own computers.","Some go so far as to build their own computers.","Some go so far to build their own computers.","Some go as so far as to build their own computers."],"answer_index":1,"explanation_cn":"go so far as to do 是固定结构,as 和 to 都不能少。✓ go so far as to build … 场合:表达“竟到了…的程度”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',9,NULL,'choice','{"stem":"你想说\"并非人人都是天生的巧匠\"(not all 部分否定):","options":["No all of us are born handymen.","Not all of us is born handymen.","All of us are not born handyman.","Not all of us are born handymen."],"answer_index":3,"explanation_cn":"not all 部分否定,us 是复数,动词用 are,名词复数 handymen;不用 is、不用 handyman、不用 No all。✓ Not all of us are born handymen. 场合:表达“并非人人都…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"dismantle 的意思是:","options":["擦亮","组装","拆卸","搬运"],"answer_index":2,"explanation_cn":"dismantle = 拆卸。✓ I decided to dismantle it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"resourceful 的意思是:","options":["胆小的","懒惰的","粗心的","足智多谋的"],"answer_index":3,"explanation_cn":"resourceful = 足智多谋的。✓ endlessly resourceful."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"\"So great ___ our passion that we depend less on experts.\"(So + 形容词提前,主语与 be 倒装)","options":["has","is","does","it is"],"answer_index":1,"stem_cn":"我们自己动手的热情如此高涨,以至于越来越少依赖专家。","explanation_cn":"So + 形容词提前引起倒装,主语单数用 is。✓ So great is our passion … ✗ does / has / it is。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"\"___ with the right tools, newlyweds decorate their homes.\"(过去分词短语作状语)","options":["To arm","Arm","Armed","Arming"],"answer_index":2,"stem_cn":"备好合适的工具,新婚夫妇装点新居。","explanation_cn":"过去分词短语作状语,表被动“备好…”。✓ Armed with the right tools, … ✗ Arming / Arm / To arm。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"\"get round to\" 的意思是:","options":["抽出时间去做","拒绝","绕道走","反复做"],"answer_index":0,"explanation_cn":"get round to = 抽出时间去做。✓ never got round to it 一直没抽时间做。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"\"embark on\" 的意思是:","options":["推迟","结束","开始(做某事)","放弃"],"answer_index":2,"explanation_cn":"embark on = 开始、着手(做某事)。✓ embark on the task of decorating."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l46',10,NULL,'choice','{"stem":"Why did the writer refuse to call a repairman?","options":["No repairman was available","He could not afford one","His wife forbade it","It was a matter of pride; he insisted on fixing the mower himself"],"answer_index":3,"passage":"So great is our passion for doing things ourselves that we are becoming less and less dependent on skilled labor. No one can plead ignorance of a subject any longer, for there are countless do-it-yourself books and videos. Armed with the right tools and materials, newlyweds gaily embark on the task of decorating their own homes. Men, in particular, spend hours of their leisure time installing their own light fixtures, laying out their own gardens, building sheds, and making furniture. Some really keen enthusiasts go so far as to build their own computers. Stores cater for the do-it-yourself craze not only by running special advice desks for novices, but by offering customers parts they can assemble at home. Such things provide an excellent outlet for pent-up creative energy, but unfortunately not all of us are born handymen. Some wives tend to believe that their husbands are endlessly resourceful and can fix anything. Even men who can hardly drive a nail in straight are supposed to be born electricians, carpenters, plumbers, and mechanics. When a fuse blows, furniture gets rickety, pipes get clogged, or the dishwasher fails to run, some women assume that their husbands will somehow put things right. The worst thing about the do-it-yourself game is that sometimes even men live under the delusion that they can do anything, even when they have repeatedly been proved wrong. It is a matter of pride as much as anything else. Last spring my wife suggested that I call in a repairman to look at our lawn mower. It had broken down the previous summer, and though I had promised to fix it, I had never gotten round to it. I would not hear of the suggestion and said that I would fix it myself. One Saturday afternoon I hauled the machine into the yard and took a close look at it. As far as I could see, it needed only a minor adjustment: a turn of a screw here, a little tightening there, a drop of oil, and it would be as good as new. Inevitably the repair job was not quite so simple. The mower firmly refused to mow, so I decided to take it apart. The yard was soon littered with chunks of metal that had once made up a lawn mower. But I was extremely pleased with myself, for I had traced the cause of the trouble. One of the links in the chain that drove the wheels had snapped. After buying a new chain, I was faced with the insurmountable task of putting the confusing jigsaw puzzle back together. I was not surprised to find that the machine still refused to work after I had reassembled it, for the simple reason that I was left with several oddly shaped bits of metal that did not seem to fit anywhere. I gave up in despair. The weeks passed and the grass grew. When my wife nagged me to do something about it, I told her that I would either have to buy a new mower or let the grass grow. Needless to say, our house is now surrounded by a jungle. Buried somewhere in the deep grass is a rusting lawn mower that I have promised to fix one day.","explanation_cn":"课文说他不愿听请修理工的建议,坚持自己修,这多半是面子问题。✓ a matter of pride."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
