INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l47','pay for','',NULL,'/peɪ fɔːr/','Pollution is the price we pay for progress.','污染是我们为进步付出的代价。','You''ll pay for this mistake.','你会为这个错误付出代价。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l47','go off','',NULL,'/ɡoʊ ɔːf/','Car alarms go off in the middle of the night.','汽车警报半夜响起。','The smoke detector went off suddenly.','烟雾报警器突然响了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l47','object to','',NULL,'/əbˈdʒekt tə/','People object to cell phones in restaurants.','人们反感在餐馆里用手机。','She objected to the noise next door.','她对隔壁的噪音表示反对。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l47','keep awake','',NULL,'/kiːp əˈweɪk/','The snoring kept her awake all night.','打鼾声让她整夜没睡。','Coffee keeps me awake at night.','咖啡让我晚上睡不着。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp1','choice','{"stem":"\"You have the choice ___ expensive organic food or cheap processed food.\"(the choice ___ A or B:在…之间选择,填介词)","options":["with","to","for","of"],"answer_index":3,"stem_cn":"你可以在昂贵有机食品和廉价加工食品之间选择。","explanation_cn":"the choice of A or B,“在 A 和 B 之间选择”;固定介词 of。✓ the choice of organic food or cheap food. ✗ for / to / with:choice 搭配 of。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp1','choice','{"stem":"\"There are four things you can do ___ garbage.\"(处理某物 do sth ___,填介词)","options":["with","of","in","at"],"answer_index":0,"stem_cn":"处理垃圾只有四种办法。","explanation_cn":"do sth with,“处置、对付某物”;things you can do with garbage 里省略了关系词。✓ four things you can do with garbage. ✗ of / in / at:“处理…”用 do with。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp1','choice','{"stem":"\"You can either recycle garbage ___ produce less of it.\"(either … ___ …:或者…或者)","options":["but","and","nor","or"],"answer_index":3,"stem_cn":"你要么回收垃圾,要么少产生垃圾。","explanation_cn":"either … or …,“或者…或者”;与 either 搭配用 or。✓ either recycle garbage or produce less. ✗ nor / and / but:与 either 搭配的是 or。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp2','choice','{"stem":"\"Dogs ___ incessantly at night are the worst noise.\"(现在分词修饰 dogs:不停吠叫的)","options":["barked","barking","to bark","bark"],"answer_index":1,"stem_cn":"夜里不停吠叫的狗是最糟的噪音。","explanation_cn":"现在分词短语放名词后修饰它,表主动“不停吠叫的”。✓ dogs barking incessantly. ✗ barked / to bark / bark:主动进行修饰名词用 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp2','choice','{"stem":"\"Car alarms ___ off at night annoy the neighbors.\"(现在分词修饰 alarms:响起的)","options":["going","to go","gone","go"],"answer_index":0,"stem_cn":"半夜响起的汽车警报吵到邻居。","explanation_cn":"现在分词修饰 alarms,“(正在)响起的”;alarm 主动发出,用 going。✓ Car alarms going off. ✗ gone / to go / go:主动进行用 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp2','choice','{"stem":"\"Lawn mowers ___ on a summer afternoon disturb everyone.\"(现在分词修饰 mowers:嗡嗡作响的)","options":["to whine","whining","whine","whined"],"answer_index":1,"stem_cn":"夏日午后嗡嗡作响的割草机搅得人人不安。","explanation_cn":"现在分词修饰 mowers,“嗡嗡作响的”。✓ Lawn mowers whining on a summer afternoon. ✗ whined / to whine / whine:主动进行用 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp3','choice','{"stem":"\"Noise is an even ___ insidious kind of pollution than garbage.\"(even + 比较级:更加…)","options":["more","most","much","very"],"answer_index":0,"stem_cn":"噪音是比垃圾更隐蔽的一种污染。","explanation_cn":"even + 比较级表“更加…”;insidious 是多音节形容词,比较级用 more insidious。✓ an even more insidious kind. ✗ most(最高级)/ very / much:比较级用 more。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp3','choice','{"stem":"\"Barking dogs rated the ___ form of noise pollution.\"(the + 最高级:最…的)","options":["high","most high","higher","highest"],"answer_index":3,"stem_cn":"吠叫的狗被评为最严重的噪音污染。","explanation_cn":"the + 最高级表“最…的”;high 的最高级是 highest。✓ rated the highest form. ✗ higher(比较级)/ high(原级)/ most high(错误变形)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp3','choice','{"stem":"\"Men are the ___ offenders when it comes to snoring.\"(the + 最高级:最坏的)","options":["worst","most bad","worse","bad"],"answer_index":0,"stem_cn":"说到打鼾,男人是最厉害的“冒犯者”。","explanation_cn":"the + 最高级;bad 的最高级是 worst。✓ the worst offenders. ✗ worse(比较级)/ bad(原级)/ most bad(错误变形)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp4','choice','{"stem":"\"Men were ___ to be the worst offenders.\"(be ___ to be…,“被发现是”,填过去分词)","options":["find","founded","found","finding"],"answer_index":2,"stem_cn":"人们发现男人是最厉害的打鼾者。","explanation_cn":"be found to do/be,“被发现是…”;用过去分词 found。✓ Men were found to be the worst offenders. ✗ find / finding / founded(founded 意为“创建”)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp4','choice','{"stem":"\"It ___ revealed that 20% of men snore.\"(被动 It ___ revealed that,据披露,填 be 动词过去式)","options":["were","was","has","is"],"answer_index":1,"stem_cn":"据披露,百分之二十的男人打鼾。","explanation_cn":"被动 It was revealed that …,“据披露…”;主语 It 单数、句子讲过去,用 was。✓ It was revealed that 20% of men snore. ✗ is(时态错)/ were(主语单数)/ has。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp4','choice','{"stem":"\"Many women are kept awake ___ their snoring partners.\"(被动 + 施动者,填介词)","options":["to","of","by","with"],"answer_index":2,"stem_cn":"许多女人被打鼾的伴侣吵得睡不着。","explanation_cn":"被动语态中动作的发出者用 by 引出。✓ kept awake by their snoring partners. ✗ of / to / with:施动者用 by。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp5','choice','{"stem":"\"___ the source of noise, silence is now rare.\"(“无论噪音来自何处”,让步)","options":["Whenever","Whatever","However","Wherever"],"answer_index":1,"stem_cn":"无论噪音来自哪里,寂静如今都很难得。","explanation_cn":"whatever + 名词引导让步状语,“无论…是什么”。✓ Whatever the source of noise, … ✗ However(接形容词/副词)/ Whenever(无论何时)/ Wherever(无论何地)。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp5','choice','{"stem":"\"Pollution is the price we pay ___ an industrialized world.\"(pay ___:为…付出代价,填介词)","options":["of","at","for","to"],"answer_index":2,"stem_cn":"污染是我们为工业化世界付出的代价。","explanation_cn":"pay for sth,“为…付出代价、买单”;固定介词 for。✓ the price we pay for an industrialized world. ✗ to / at / of:pay 搭配 for。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp5','choice','{"stem":"\"___ these figures, only 5% of women snore.\"(“与这些数字相比”:___ these figures)","options":["By","Against","On","For"],"answer_index":1,"stem_cn":"与这些数字相比,只有百分之五的女性经常打鼾。","explanation_cn":"against these figures,“与这些数字相比”;固定用 against。✓ Against these figures, only 5% of women snore. ✗ For / By / On:此处固定用 Against。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp6','choice','{"stem":"\"Something harmful in a hidden, gradual way is ___.\"(“暗中为害的”用哪个词)","options":["insidious","harmless","obvious","gentle"],"answer_index":0,"stem_cn":"暗中逐渐为害的。","explanation_cn":"在暗中、逐渐为害的是 insidious。✓ an even more insidious kind of pollution. ✗ obvious 明显;✗ harmless 无害;✗ gentle 温和——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp6','choice','{"stem":"\"To defeat or bury someone completely is to ___ them.\"(“制服、使不知所措”用哪个词)","options":["protect","greet","relax","overwhelm"],"answer_index":3,"stem_cn":"彻底压倒、使人不知所措。","explanation_cn":"彻底压倒、使人不知所措是 overwhelm。✓ threatens to overwhelm us. ✗ protect 保护;✗ relax 放松;✗ greet 问候——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',5,'am3_l47_gp6','choice','{"stem":"\"A number so large it shocks you is ___.\"(“令人惊愕的”用哪个词)","options":["ordinary","exact","staggering","tiny"],"answer_index":2,"stem_cn":"大得令人惊愕的数字。","explanation_cn":"大得令人惊愕是 staggering。✓ a staggering sixty percent. ✗ tiny 极小;✗ ordinary 普通;✗ exact 精确——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"pollution 的意思是:","options":["污染","回收","预报","治理"],"answer_index":0,"explanation_cn":"pollution = 污染。✓ the problem of pollution 污染问题。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"overwhelm 的意思是:","options":["忽视","制服,使不知所措","照亮","欢迎"],"answer_index":1,"explanation_cn":"overwhelm = 制服、使不知所措。✓ threatens to overwhelm us 有把我们淹没的危险。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"insidious 的意思是:","options":["短暂的","明显的","无害的","暗中为害的"],"answer_index":3,"explanation_cn":"insidious = 暗中为害的。✓ an insidious kind of pollution 一种隐蔽的污染。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"incessantly 的意思是:","options":["安静地","偶尔地","连续不断地","迅速地"],"answer_index":2,"explanation_cn":"incessantly = 连续不断地。✓ dogs barking incessantly 不停吠叫的狗。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"staggering 的意思是:","options":["令人惊愕的","十分普通的","微不足道的","缓慢的"],"answer_index":0,"explanation_cn":"staggering = 令人惊愕的。✓ a staggering sixty percent 令人惊愕的百分之六十。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',6,NULL,'choice','{"stem":"offender 的意思是:","options":["保护者","冒犯者,违规者","受害者","旁观者"],"answer_index":1,"explanation_cn":"offender = 冒犯者、违规者。✓ the worst offenders 最厉害的“冒犯者”。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',7,NULL,'cloze','{"stem":"第 1 空","context":"Pollution is the price we ___1___ for an overpopulated, over-industrialized planet. Garbage is only part of the problem. There is an even ___2___ insidious kind of pollution: noise. A survey found that dogs ___3___ incessantly at night rated the highest. Surprisingly, snoring was on the list too: men ___4___ found to be the worst offenders.","blank_no":1,"options":["pay","cost","spend","buy"],"answer_index":0,"explanation_cn":"pay for sth,“为…付出代价”;此处填 pay。✓ the price we pay for … ✗ cost / spend / buy:与 price…for 搭配用 pay。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',7,NULL,'cloze','{"stem":"第 2 空","context":"Pollution is the price we ___1___ for an overpopulated, over-industrialized planet. Garbage is only part of the problem. There is an even ___2___ insidious kind of pollution: noise. A survey found that dogs ___3___ incessantly at night rated the highest. Surprisingly, snoring was on the list too: men ___4___ found to be the worst offenders.","blank_no":2,"options":["more","most","very","much"],"answer_index":0,"explanation_cn":"even + 比较级“更加…”;insidious 用 more。✓ an even more insidious kind."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',7,NULL,'cloze','{"stem":"第 3 空","context":"Pollution is the price we ___1___ for an overpopulated, over-industrialized planet. Garbage is only part of the problem. There is an even ___2___ insidious kind of pollution: noise. A survey found that dogs ___3___ incessantly at night rated the highest. Surprisingly, snoring was on the list too: men ___4___ found to be the worst offenders.","blank_no":3,"options":["barking","barked","to bark","bark"],"answer_index":0,"explanation_cn":"现在分词修饰 dogs,“不停吠叫的”。✓ dogs barking incessantly."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',7,NULL,'cloze','{"stem":"第 4 空","context":"Pollution is the price we ___1___ for an overpopulated, over-industrialized planet. Garbage is only part of the problem. There is an even ___2___ insidious kind of pollution: noise. A survey found that dogs ___3___ incessantly at night rated the highest. Surprisingly, snoring was on the list too: men ___4___ found to be the worst offenders.","blank_no":4,"options":["were","was","are","is"],"answer_index":0,"explanation_cn":"被动 men were found to be;主语 men 复数,用 were。✓ men were found to be the worst offenders."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',8,NULL,'choice','{"stem":"What amusing old-fashioned source of noise did the survey reveal?","options":["Steam trains","Church bells","Street musicians","Snoring"],"answer_index":3,"explanation_cn":"录音说调查揭示出一个出人意料、甚至好笑的老式噪音源,原来是打鼾。✓ snoring."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',8,NULL,'choice','{"stem":"Which sound rated the highest form of noise pollution?","options":["Lawn mowers","Car alarms","Dogs barking incessantly at night","Cell phones"],"answer_index":2,"explanation_cn":"录音说在一到七的评分上,夜里不停吠叫的狗被列为最严重的噪音污染。✓ dogs barking incessantly."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',8,NULL,'choice','{"stem":"According to the survey, who are the worst snorers?","options":["Small children","Men, especially older men","Teenagers","Young women"],"answer_index":1,"explanation_cn":"录音说男人是最厉害的打鼾者,且年纪越大比例越高。✓ men, especially older men."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',9,NULL,'choice','{"stem":"你想说\"你可以在昂贵有机食品和廉价食品之间选择\"(the choice of A or B):","options":["You have choice of expensive organic food or cheap food.","You have the choice for expensive organic food or cheap food.","You have the choice of expensive organic food or cheap food.","You have the choice of expensive organic food nor cheap food."],"answer_index":2,"explanation_cn":"the choice of A or B,介词用 of、连接用 or;choice 前不能少冠词。✓ the choice of … or … 场合:在两者间选择。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',9,NULL,'choice','{"stem":"你想说\"许多女人被打鼾的伴侣吵得睡不着\"(被动 + by):","options":["Many women are kept awake of their snoring partners.","Many women are kept awake by their snoring partners.","Many women are kept awake with their snoring partners.","Many women keep awake by their snoring partners."],"answer_index":1,"explanation_cn":"被动 be kept awake,动作发出者用 by;不用 with/of,also 不能写成主动 keep。✓ are kept awake by … 场合:被…吵得睡不着。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',9,NULL,'choice','{"stem":"你想说\"无论噪音来自何处,寂静都已难得\"(whatever 让步):","options":["Whatever the source of noise, silence is now rare.","However the source of noise, silence is now rare.","Whenever the source of noise, silence is now rare.","What the source of noise, silence is now rare."],"answer_index":0,"explanation_cn":"whatever + 名词引导让步(无论…是什么);不用 however/whenever/what。✓ Whatever the source of noise, … 场合:表达“无论…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"insidious 的意思是:","options":["暗中为害的","无害的","短暂的","明显的"],"answer_index":0,"explanation_cn":"insidious = 暗中为害的。✓ an insidious kind of pollution."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"staggering 的意思是:","options":["十分普通的","缓慢的","微不足道的","令人惊愕的"],"answer_index":3,"explanation_cn":"staggering = 令人惊愕的。✓ a staggering sixty percent."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"\"You have the choice ___ organic food or cheap food.\"(the choice ___ A or B:在…之间选择)","options":["with","of","for","to"],"answer_index":1,"stem_cn":"你可以在有机食品和廉价食品之间选择。","explanation_cn":"the choice of A or B,固定介词 of。✓ the choice of organic food or cheap food. ✗ for / to / with。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"\"Men were ___ to be the worst offenders.\"(be ___ to be…,“被发现是”,填过去分词)","options":["found","founded","finding","find"],"answer_index":0,"stem_cn":"人们发现男人是最厉害的打鼾者。","explanation_cn":"be found to be,“被发现是…”,用过去分词 found。✓ Men were found to be the worst offenders. ✗ find / finding / founded。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"\"go off\" 的意思是:","options":["熄灭、关掉","出发离开","(警报等)突然响起","变质"],"answer_index":2,"explanation_cn":"go off = (警报、闹钟等)突然响起。✓ Car alarms go off in the night."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"\"object to\" 的意思是:","options":["描述","赞成","提出","反对、不喜欢"],"answer_index":3,"explanation_cn":"object to = 反对、不喜欢。✓ people object to cell phones 人们反感手机。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"According to the writer, what are the four ways to deal with garbage?","options":["Wash it, dry it, fold it, or store it","Export it, freeze it, crush it, or paint it","Dump it, burn it, recycle it, or produce less of it","Bury it, sell it, hide it, or ignore it"],"answer_index":2,"passage":"Pollution is the price we pay for an overpopulated, over-industrialized planet. When you stop to think about it, there are only four things you can do with garbage: dump it, burn it, turn it into something you can use again, or try to produce less of it. We keep trying all four methods, but the sheer volume of garbage we produce worldwide threatens to overwhelm us. Garbage, however, is only part of the problem of polluting our planet. The need to produce ever-larger quantities of cheap food leads to a different kind of pollution. Industrialized farming methods produce cheap meat, and the heavy use of pesticides and fertilizers produces cheap grain and vegetables. The price we pay for cheap food may already be too high. And if you think you will give up meat and become a vegetarian, you have the choice of either very expensive organically-grown vegetables or a steady diet of pesticides every time you eat what looks like a fresh salad. However, there is an even more insidious kind of pollution that especially affects urban areas and invades our daily lives, and that is noise. Car alarms going off in the middle of the night serve only to annoy the neighbors. Sirens and jackhammers scream at us in the street and are a source of profound irritation. A recent survey of the effects of noise revealed, perhaps surprisingly, that dogs barking incessantly at night rated the highest form of noise pollution on a scale ranging from one to seven. The survey turned up a long list of sounds that people really dislike: lawn mowers whining on a summer afternoon, late-night parties in apartment buildings, noisy neighbors, big container trucks thundering through quiet towns, planes and helicopters flying overhead, and loud music played at maximum volume in public places. New technology has made its own contribution to noise, too. Many people object to cell phones, especially when they are used in restaurants or on public transportation, where loud conversations invade our thoughts and interrupt the pleasure of a quiet chat with friends. The survey also revealed a rather surprising and possibly amusing old-fashioned source of noise. It turned out to be snoring! Men were found to be the worst offenders. It was revealed that twenty percent of men in their mid-thirties snore, and that this figure rises to a staggering sixty percent of men in their sixties. Against these figures, it was found that only five percent of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners. Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","explanation_cn":"课文说处理垃圾只有四种办法:倾倒、焚烧、变成可再利用的东西、或少产生。✓ dump/burn/recycle/produce less."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"Why does the writer say the price of cheap food may be too high?","options":["Cheap food is always imported","Cheap food comes with pesticides, and cheap meat brings disease risks","Cheap food is hard to find","Cheap food simply tastes bad"],"answer_index":1,"passage":"Pollution is the price we pay for an overpopulated, over-industrialized planet. When you stop to think about it, there are only four things you can do with garbage: dump it, burn it, turn it into something you can use again, or try to produce less of it. We keep trying all four methods, but the sheer volume of garbage we produce worldwide threatens to overwhelm us. Garbage, however, is only part of the problem of polluting our planet. The need to produce ever-larger quantities of cheap food leads to a different kind of pollution. Industrialized farming methods produce cheap meat, and the heavy use of pesticides and fertilizers produces cheap grain and vegetables. The price we pay for cheap food may already be too high. And if you think you will give up meat and become a vegetarian, you have the choice of either very expensive organically-grown vegetables or a steady diet of pesticides every time you eat what looks like a fresh salad. However, there is an even more insidious kind of pollution that especially affects urban areas and invades our daily lives, and that is noise. Car alarms going off in the middle of the night serve only to annoy the neighbors. Sirens and jackhammers scream at us in the street and are a source of profound irritation. A recent survey of the effects of noise revealed, perhaps surprisingly, that dogs barking incessantly at night rated the highest form of noise pollution on a scale ranging from one to seven. The survey turned up a long list of sounds that people really dislike: lawn mowers whining on a summer afternoon, late-night parties in apartment buildings, noisy neighbors, big container trucks thundering through quiet towns, planes and helicopters flying overhead, and loud music played at maximum volume in public places. New technology has made its own contribution to noise, too. Many people object to cell phones, especially when they are used in restaurants or on public transportation, where loud conversations invade our thoughts and interrupt the pleasure of a quiet chat with friends. The survey also revealed a rather surprising and possibly amusing old-fashioned source of noise. It turned out to be snoring! Men were found to be the worst offenders. It was revealed that twenty percent of men in their mid-thirties snore, and that this figure rises to a staggering sixty percent of men in their sixties. Against these figures, it was found that only five percent of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners. Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","explanation_cn":"课文说廉价蔬菜伴随杀虫剂、廉价肉类带来疾病风险,故代价太高。✓ pesticides + disease risks."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"How does the percentage of snoring men change with age?","options":["It falls steadily as men get older","It stays the same all through life","Only 5% of men ever snore","It rises from about 20% in their mid-thirties to about 60% in their sixties"],"answer_index":3,"audio":"Pollution is the price we pay for an overpopulated, over-industrialized planet. When you stop to think about it, there are only four things you can do with garbage: dump it, burn it, turn it into something you can use again, or try to produce less of it. We keep trying all four methods, but the sheer volume of garbage we produce worldwide threatens to overwhelm us. Garbage, however, is only part of the problem of polluting our planet. The need to produce ever-larger quantities of cheap food leads to a different kind of pollution. Industrialized farming methods produce cheap meat, and the heavy use of pesticides and fertilizers produces cheap grain and vegetables. The price we pay for cheap food may already be too high. And if you think you will give up meat and become a vegetarian, you have the choice of either very expensive organically-grown vegetables or a steady diet of pesticides every time you eat what looks like a fresh salad. However, there is an even more insidious kind of pollution that especially affects urban areas and invades our daily lives, and that is noise. Car alarms going off in the middle of the night serve only to annoy the neighbors. Sirens and jackhammers scream at us in the street and are a source of profound irritation. A recent survey of the effects of noise revealed, perhaps surprisingly, that dogs barking incessantly at night rated the highest form of noise pollution on a scale ranging from one to seven. The survey turned up a long list of sounds that people really dislike: lawn mowers whining on a summer afternoon, late-night parties in apartment buildings, noisy neighbors, big container trucks thundering through quiet towns, planes and helicopters flying overhead, and loud music played at maximum volume in public places. New technology has made its own contribution to noise, too. Many people object to cell phones, especially when they are used in restaurants or on public transportation, where loud conversations invade our thoughts and interrupt the pleasure of a quiet chat with friends. The survey also revealed a rather surprising and possibly amusing old-fashioned source of noise. It turned out to be snoring! Men were found to be the worst offenders. It was revealed that twenty percent of men in their mid-thirties snore, and that this figure rises to a staggering sixty percent of men in their sixties. Against these figures, it was found that only five percent of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners. Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","explanation_cn":"课文说三十五岁上下约百分之二十打鼾,到六十多岁升到约百分之六十。✓ 20%→60%."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l47',10,NULL,'choice','{"stem":"What has silence become, according to the writer?","options":["A kind of pollution","A daily habit","A golden memory","A new law"],"answer_index":2,"audio":"Pollution is the price we pay for an overpopulated, over-industrialized planet. When you stop to think about it, there are only four things you can do with garbage: dump it, burn it, turn it into something you can use again, or try to produce less of it. We keep trying all four methods, but the sheer volume of garbage we produce worldwide threatens to overwhelm us. Garbage, however, is only part of the problem of polluting our planet. The need to produce ever-larger quantities of cheap food leads to a different kind of pollution. Industrialized farming methods produce cheap meat, and the heavy use of pesticides and fertilizers produces cheap grain and vegetables. The price we pay for cheap food may already be too high. And if you think you will give up meat and become a vegetarian, you have the choice of either very expensive organically-grown vegetables or a steady diet of pesticides every time you eat what looks like a fresh salad. However, there is an even more insidious kind of pollution that especially affects urban areas and invades our daily lives, and that is noise. Car alarms going off in the middle of the night serve only to annoy the neighbors. Sirens and jackhammers scream at us in the street and are a source of profound irritation. A recent survey of the effects of noise revealed, perhaps surprisingly, that dogs barking incessantly at night rated the highest form of noise pollution on a scale ranging from one to seven. The survey turned up a long list of sounds that people really dislike: lawn mowers whining on a summer afternoon, late-night parties in apartment buildings, noisy neighbors, big container trucks thundering through quiet towns, planes and helicopters flying overhead, and loud music played at maximum volume in public places. New technology has made its own contribution to noise, too. Many people object to cell phones, especially when they are used in restaurants or on public transportation, where loud conversations invade our thoughts and interrupt the pleasure of a quiet chat with friends. The survey also revealed a rather surprising and possibly amusing old-fashioned source of noise. It turned out to be snoring! Men were found to be the worst offenders. It was revealed that twenty percent of men in their mid-thirties snore, and that this figure rises to a staggering sixty percent of men in their sixties. Against these figures, it was found that only five percent of women snore regularly, while the rest are constantly woken or kept awake by their trumpeting partners. Whatever the source of noise, one thing is certain: silence, it seems, has become a golden memory.","explanation_cn":"课文结尾说寂静似乎已成了一段珍贵(金子般)的回忆。✓ a golden memory."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
